#include <cstdio>
#include <cstdint>
#include <vector>

struct Cache {
    int nlines;
    std::vector<long long> tag;
    long long miss = 0;
    explicit Cache(int n) : nlines(n), tag(n, -1) {}
    void access(const void* p) {
        long long t = (long long)((uintptr_t)p / 64);
        int idx = (int)(t % nlines);
        if (tag[idx] != t) { ++miss; tag[idx] = t; }
    }
    void reset() { for (auto& x : tag) x = -1; miss = 0; }
};

const int M = 1024;
std::vector<int> mat((size_t)M * M, 1);     // 行优先存储的 M×M 矩阵

int main() {
    Cache c(256);
    long long acc = 0;

    // 行优先遍历：内层沿行方向连续推进 → 空间局部性最好
    for (int i = 0; i < M; ++i)
        for (int j = 0; j < M; ++j) {
            c.access(&mat[(size_t)i * M + j]);
            acc += mat[(size_t)i * M + j];
        }
    long long row_miss = c.miss;

    c.reset();
    // 列优先遍历：内层跨行跳（步长 M*4=4096 字节 = 64 行）→ 每次都换行
    for (int j = 0; j < M; ++j)
        for (int i = 0; i < M; ++i) {
            c.access(&mat[(size_t)i * M + j]);
            acc += mat[(size_t)i * M + j];
        }
    long long col_miss = c.miss;

    printf("行优先未命中=%lld 列优先未命中=%lld\n", row_miss, col_miss);
    printf("行优先更省缓存行: %d\n", (int)(row_miss < col_miss));
    printf("列优先/行优先 倍数=%lld\n", col_miss / row_miss);
    printf("校验和=%lld\n", acc);
    return 0;
}
